// FUNCTION: BFME2 0x00172D40 size=199 name=?Replace_VertexMaterial@MeshModelClass@@QAEXPAVVertexMaterialClass@@0@Z evidence=N:ledger tier=B hypothesis:K
void MeshModelClass::Replace_VertexMaterial(VertexMaterialClass *vmat, VertexMaterialClass *new_vmat)
{
	for (int pass = 0; pass < CurMatDesc->Get_Pass_Count(); pass++) {
		if (CurMatDesc->Has_Material_Array(pass)) {
			for (int vert = 0; vert < VertexCount; vert++) {
				if (CurMatDesc->Peek_Material(vert, pass) == vmat)
					CurMatDesc->Set_Material(vert, new_vmat, pass);
			}
		} else if (CurMatDesc->Peek_Single_Material(pass) == vmat) {
			CurMatDesc->Set_Single_Material(new_vmat, pass);
		}

		// Renderers already registered keep their own material references.
		DX8FVFCategoryContainer *container = Peek_FVF_Category_Container();
		if (container != NULL)
			container->Change_Polygon_Renderer_Material(PolygonRendererList, vmat, new_vmat, pass);
	}
}

